2	#define SG_FUSED_SM90_DECODER_LAYOUT_CUH_
3	// ============================================================================
4	// csrc/fused/sm_90/decoder_layout.cuh — GENERATED weight-layout mirror for the
5	// L3-REAL transformer-decoder megakernel (PHASE 1).
6	//
7	// AUTO-GENERATED by: python -m grokking_optimizers.megakernel_codegen \
8	//     --decoder-layout > csrc/fused/sm_90/decoder_layout.cuh
9	// Do NOT hand-edit the numbers. SINGLE SOURCE OF TRUTH: megakernel_codegen.py
10	// _decoder_param_sizes() (mirrored by tests/hw/decoder_oracle.py, asserted ==
11	// the eager model's named_parameters() order in the parity test). The flat blob
12	// is torch.cat([p.reshape(-1) for _, p in model.named_parameters()]); the kernel
13	// addresses tensor i at params + kDecOffsets[i] for kDecSizes[i] elements.
14	//
15	// A count/total mismatch fails the BUILD loudly (a static_assert below), never
16	// corrupts at dispatch.
17	// ============================================================================
18	
19	#include <cstdint>
20	
21	namespace sg { namespace fused { namespace sm90 {
22	
23	constexpr int SG_DEC_VOCAB  = 99;
24	constexpr int SG_DEC_D      = 128;
25	constexpr int SG_DEC_HEADS  = 4;
26	constexpr int SG_DEC_LAYERS = 2;
27	constexpr int SG_DEC_SEQ    = 4;
28	constexpr int SG_DEC_DFF    = 4 * SG_DEC_D;   // 512
29	
30	constexpr int     kDecNumTensors = 30;
31	constexpr int64_t kDecTotalElems = 422755;
32	
33	// Per-tensor element offsets into the flat param blob, named_parameters() order.
34	__device__ __constant__ int kDecOffsets[kDecNumTensors] = {
35	    0, 12672, 13184, 62336, 62720, 79104, 79232, 79360, 79488, 79616,
36	    79744, 145280, 145792, 211328, 211456, 260608, 260992, 277376, 277504, 277632,
37	    277760, 277888, 278016, 343552, 344064, 409600, 409728, 409856, 409984, 422656
38	};
39	
40	// Per-tensor element sizes (numel), same order.
41	__device__ __constant__ int kDecSizes[kDecNumTensors] = {
42	    12672, 512, 49152, 384, 16384, 128, 128, 128, 128, 128,
43	    65536, 512, 65536, 128, 49152, 384, 16384, 128, 128, 128,
44	    128, 128, 65536, 512, 65536, 128, 128, 128, 12672, 99
45	};
46	
47	static_assert(kDecNumTensors == 30,
48	              "decoder_layout: tensor count drifted. Regenerate via "
49	              "megakernel_codegen.py --decoder-layout.");
50	static_assert(kDecTotalElems == 422755,
51	              "decoder_layout: total param count drifted. Regenerate.");
52	
53	// Host-constexpr mirrors so a sum/offset cross-check folds at compile time (a
54	// __constant__ array can't be folded in a constexpr). These guarantee
55	// offsets/sizes/total agree.
56	namespace dec_layout_check {
57	constexpr int kSizes[kDecNumTensors] = {
58	    12672, 512, 49152, 384, 16384, 128, 128, 128, 128, 128,
59	    65536, 512, 65536, 128, 49152, 384, 16384, 128, 128, 128,
60	    128, 128, 65536, 512, 65536, 128, 128, 128, 12672, 99
61	};
62	constexpr int kOffsets[kDecNumTensors] = {
63	    0, 12672, 13184, 62336, 62720, 79104, 79232, 79360, 79488, 79616,
64	    79744, 145280, 145792, 211328, 211456, 260608, 260992, 277376, 277504, 277632,
65	    277760, 277888, 278016, 343552, 344064, 409600, 409728, 409856, 409984, 422656
66	};
67	constexpr int64_t sum_sizes() {
68	    int64_t s = 0;
69	    for (int i = 0; i < kDecNumTensors; ++i) s += kSizes[i];
70	    return s;
71	}
72	constexpr bool offsets_consistent() {
73	    int64_t acc = 0;
74	    for (int i = 0; i < kDecNumTensors; ++i) {
75	        if (kOffsets[i] != (int)acc) return false;
76	        acc += kSizes[i];
77	    }
78	    return true;
79	}
80	static_assert(sum_sizes() == kDecTotalElems,
81	              "decoder_layout: sum(kDecSizes) != kDecTotalElems. Regenerate.");
82	static_assert(offsets_consistent(),
83	              "decoder_layout: kDecOffsets[i] != sum(kDecSizes[0..i)). Regenerate.");
84	}  // namespace dec_layout_check
85	
86	}}} // namespace sg::fused::sm90
