652	// ────────────────────────────────────────────────────────────────────────────
653	//  BACKWARD for one sample (CTA-cooperative). Assumes dec_forward_sample has run
654	//  for THIS sample (so layer_in/final_in/fn caches/logits are populated and
655	//  reflect this sample). Accumulates every weight grad into the CTA's partial
656	//  buffer `g` (DecGrad over gw_cta). Uses extra smem scratch passed via sm.
657	//
658	//  Transcribed from tests/hw/decoder_oracle.py::decoder_backward.
659	// ────────────────────────────────────────────────────────────────────────────
660	__device__ void dec_backward_sample(const DecWeights& w, const DecGrad& g,
661	                                     const int* tokens_s, int target, int B,
662	                                     DecSampleSmem* sm) {
663	    // ── CE backward: dlogits = (softmax - onehot)/B. (logits cached in fwd.) ──
664	    float lmax = -CUDART_INF_F;
665	    for (int o = threadIdx.x; o < dec::kVocab; o += blockDim.x)
666	        lmax = fmaxf(lmax, sm->logits[o]);
667	    lmax = dec_block_max(lmax, sm->red);
668	    float es = 0.0f;
669	    for (int o = threadIdx.x; o < dec::kVocab; o += blockDim.x)
670	        es += __expf(sm->logits[o] - lmax);
671	    es = dec_block_sum(es, sm->red);
672	    float inv_es = 1.0f / es;
673	    // overwrite logits[] with dlogits in place.
674	    for (int o = threadIdx.x; o < dec::kVocab; o += blockDim.x) {
675	        float sm_o = __expf(sm->logits[o] - lmax) * inv_es;
676	        float dl = (sm_o - ((o == target) ? 1.0f : 0.0f)) / (float)B;
677	        sm->logits[o] = dl;
678	    }
679	    __syncthreads();
680	    // ── head (out): logits = hn @ out_w^T + out_b. hn was stashed in x1[0]
681	    //    during fwd, but x1 has since been reused — recompute hn from the
682	    //    cached final-norm: hn[j] = fn_xhat[last][j]*norm_w[j] + norm_b[j]. ──
683	    // dW_out[o,:] += dlogits[o] * hn ; db_out[o] += dlogits[o].
684	    // dhn[j] = sum_o dlogits[o] * out_w[o,j].
685	    for (int o = threadIdx.x; o < dec::kVocab; o += blockDim.x) {
686	        float dl = sm->logits[o];
687	        g.out_b[o] += dl;
688	        float* gwrow = g.out_w + (int64_t)o * dec::kD;
689	        const float* xh = &sm->fn_xhat[dec::kSeq - 1][0];
690	        #pragma unroll 4
691	        for (int j = 0; j < dec::kD; ++j) {
692	            float hn_j = xh[j] * w.norm_w[j] + w.norm_b[j];
693	            gwrow[j] += dl * hn_j;
694	        }
695	    }
696	    __syncthreads();
697	    // dhn[j] (feature-parallel) into dh row 0 scratch.
698	    for (int j = threadIdx.x; j < dec::kD; j += blockDim.x) {
699	        float acc = 0.0f;
700	        for (int o = 0; o < dec::kVocab; ++o)
701	            acc += sm->logits[o] * w.out_w[(int64_t)o * dec::kD + j];
702	        sm->dh[0][j] = acc;   // dhn
703	    }
704	    __syncthreads();
705	    // ── final norm backward: dy=dhn (row last), xhat=fn_xhat[last], inv=fn_inv.
706	    //    Produces dh_last into dh[last]; accumulate dnorm_w/dnorm_b. Use a single
707	    //    "position" (last). Build a 1-row dy view: reuse sm->ctx row last = dhn. ─
708	    for (int j = threadIdx.x; j < dec::kD; j += blockDim.x)
709	        sm->ctx[dec::kSeq - 1][j] = sm->dh[0][j];   // dy at last position
710	    __syncthreads();
711	    // dnorm_w/dnorm_b: only the last position contributes (others have dy=0).
712	    for (int j = threadIdx.x; j < dec::kD; j += blockDim.x) {
713	        float d = sm->ctx[dec::kSeq - 1][j];
714	        float xh = sm->fn_xhat[dec::kSeq - 1][j];
715	        g.norm_b[j] += d; g.norm_w[j] += d * xh;
716	    }
717	    __syncthreads();
718	    // dx for the last position (LN backward, single row).
719	    {
720	        const float* dyr = &sm->ctx[dec::kSeq - 1][0];
721	        const float* xhr = &sm->fn_xhat[dec::kSeq - 1][0];
722	        float sda = 0.0f, sdax = 0.0f;
723	        for (int j = threadIdx.x; j < dec::kD; j += blockDim.x) {
724	            float dxhat = dyr[j] * w.norm_w[j];
725	            sda += dxhat; sdax += dxhat * xhr[j];
726	        }
727	        sda = dec_block_sum(sda, sm->red);
728	        sdax = dec_block_sum(sdax, sm->red);
729	        float inv_s = sm->fn_inv[0];
730	        for (int j = threadIdx.x; j < dec::kD; j += blockDim.x) {
731	            float dxhat = dyr[j] * w.norm_w[j];
732	            // dh[s,:] = 0 for s<last; last gets the LN dx.
733	            for (int s = 0; s < dec::kSeq; ++s) sm->dh[s][j] = 0.0f;
734	            sm->dh[dec::kSeq - 1][j] =
735	                inv_s * (dxhat - (sda + xhr[j] * sdax) / (float)dec::kD);
736	        }
737	        __syncthreads();
738	    }
739	    // dh now = grad wrt the last layer's OUTPUT [kSeq,d] (only last pos nonzero).
740	
741	    // ── per-layer backward (reverse). Each layer: recompute fwd intermediates,
742	    //    then apply the chain. We use sm scratch heavily; the running adjoint
743	    //    `dh` is preserved across the recompute (recompute writes qkv/x1/ff0/
744	    //    gact/attn/ctx + LN caches; it temporarily uses sm->dh as ff2 scratch —
745	    //    so SAVE dh into final_in (free after fwd) around the recompute). ───────
746	    for (int li = dec::kLayers - 1; li >= 0; --li) {
747	        const DecWeights::Layer& L = w.layer[li];
748	        const DecGrad::Layer& G = g.layer[li];
749	        // Save the incoming adjoint dh into final_in (unused now) — recompute
750	        // clobbers sm->dh.
751	        for (int idx = threadIdx.x; idx < dec::kSeq * dec::kD; idx += blockDim.x) {
752	            const int s = idx / dec::kD, j = idx % dec::kD;
753	            sm->final_in[s][j] = sm->dh[s][j];
754	        }
755	        __syncthreads();
756	        dec_recompute_layer(w, li, sm);   // fills qkv,x1,ff0,gact,attn,ctx(=r2),caches
757	        // Restore dh (grad wrt h2 = n2 output).
758	        for (int idx = threadIdx.x; idx < dec::kSeq * dec::kD; idx += blockDim.x) {
759	            const int s = idx / dec::kD, j = idx % dec::kD;
760	            sm->dh[s][j] = sm->final_in[s][j];
761	        }
762	        __syncthreads();
763	        // n2 backward: dh -> dr2, accumulate n2 gamma/beta. Put dr2 into ctx
764	        // (currently r2 — we no longer need r2's value, only its caches).
765	        dec_layernorm_bwd(&sm->dh[0][0], &sm->n2_xhat[0][0], &sm->n2_inv[0],
766	                          L.n2_w, &sm->ctx[0][0], G.n2_w, G.n2_b, sm->red, true);
767	        // r2 = x1 + ff2 → both branches get dr2: dx1 (residual) and dff2.
768	        // SMEM map (one layer live; values consumed before each reuse — verified
769	        // alias-safe by the structural mirror): dx1 lives in `fn_xhat` (final-norm
770	        // caches are done), dr2 stays in `ctx`. x_in = layer_in[li] is NOT touched
771	        // (in_proj bwd needs it); qkv is NOT touched (attention bwd needs q/k/v).
772	        for (int idx = threadIdx.x; idx < dec::kSeq * dec::kD; idx += blockDim.x) {
773	            const int s = idx / dec::kD, j = idx % dec::kD;
774	            sm->fn_xhat[s][j] = sm->ctx[s][j];   // dx1 := dr2 (residual part)
775	        }
776	        __syncthreads();
777	        // ff.2 backward. dgact = dr2 @ ff2_w is needed only to form
778	        // dff0 = dgact * gelu'(ff0); since `ff0` (pre-gelu) is needed for gelu'(),
779	        // we compute dgact and immediately fold gelu' so dff0 is written OVER
780	        // `gact` (its forward value g is consumed by the dW_ff2 GEMM first). No
781	        // extra scratch buffer is needed.
782	        //   dW_ff2 += dr2^T @ g ; db_ff2 += Σ dr2.
783	        {
784	            const float* dY = &sm->ctx[0][0];   // dr2 [kSeq,d]
785	            const float* X = &sm->gact[0][0];   // g [kSeq,4d]
786	            // dW ff2 [d,4d]
787	            const int wtot = dec::kD * dec::kDff;
788	            for (int idx = threadIdx.x; idx < wtot; idx += blockDim.x) {
789	                const int o = idx / dec::kDff, i = idx % dec::kDff;
790	                float acc = 0.0f;
791	                #pragma unroll
792	                for (int s = 0; s < dec::kSeq; ++s)
793	                    acc += dY[s * dec::kD + o] * X[s * dec::kDff + i];
794	                G.ff2_w[(int64_t)o * dec::kDff + i] += acc;
795	            }
796	            for (int o = threadIdx.x; o < dec::kD; o += blockDim.x) {
797	                float acc = 0.0f;
798	                #pragma unroll
799	                for (int s = 0; s < dec::kSeq; ++s) acc += dY[s * dec::kD + o];
800	                G.ff2_b[o] += acc;
801	            }
802	            __syncthreads();
803	            // dff0 = (dr2 @ ff2_w) * gelu'(ff0), written OVER gact.
804	            const int xtot = dec::kSeq * dec::kDff;
805	            for (int idx = threadIdx.x; idx < xtot; idx += blockDim.x) {
806	                const int s = idx / dec::kDff, i = idx % dec::kDff;
807	                float dg = 0.0f;
808	                for (int o = 0; o < dec::kD; ++o)
809	                    dg += dY[s * dec::kD + o] * L.ff2_w[(int64_t)o * dec::kDff + i];
810	                sm->gact[s][i] = dg * dec_gelu_grad(sm->ff0[s][i]);  // gact := dff0
811	            }
812	            __syncthreads();
813	        }
814	        // ff.0 backward: dY=dff0 (=gact), X=x1 -> dW ff0, db ff0, dx1 += dff0 @ ff0_w.
815	        // dx1 currently in fn_xhat (residual part); ADD the FFN path.
816	        {
817	            const float* dY = &sm->gact[0][0];   // dff0 [kSeq,4d]
818	            const float* X = &sm->x1[0][0];      // x1 [kSeq,d]
819	            const int wtot = dec::kDff * dec::kD;
820	            for (int idx = threadIdx.x; idx < wtot; idx += blockDim.x) {
821	                const int o = idx / dec::kD, i = idx % dec::kD;
822	                float acc = 0.0f;
823	                #pragma unroll
824	                for (int s = 0; s < dec::kSeq; ++s)
825	                    acc += dY[s * dec::kDff + o] * X[s * dec::kD + i];
826	                G.ff0_w[(int64_t)o * dec::kD + i] += acc;
827	            }
828	            for (int o = threadIdx.x; o < dec::kDff; o += blockDim.x) {
829	                float acc = 0.0f;
830	                #pragma unroll
831	                for (int s = 0; s < dec::kSeq; ++s) acc += dY[s * dec::kDff + o];
832	                G.ff0_b[o] += acc;
833	            }
834	            __syncthreads();
835	            const int xtot = dec::kSeq * dec::kD;
836	            for (int idx = threadIdx.x; idx < xtot; idx += blockDim.x) {
837	                const int s = idx / dec::kD, i = idx % dec::kD;
838	                float acc = 0.0f;
839	                for (int o = 0; o < dec::kDff; ++o)
840	                    acc += dY[s * dec::kDff + o] * L.ff0_w[(int64_t)o * dec::kD + i];
841	                sm->fn_xhat[s][i] += acc;   // dx1 += FFN path
842	            }
843	            __syncthreads();
844	        }
845	        // dx1 (in fn_xhat) -> n1 backward -> dr1 (into ctx). accumulate n1 g/b.
846	        dec_layernorm_bwd(&sm->fn_xhat[0][0], &sm->n1_xhat[0][0], &sm->n1_inv[0],
847	                          L.n1_w, &sm->ctx[0][0], G.n1_w, G.n1_b, sm->red, true);
848	        // r1 = x_in + a -> da = dr1 ; dx_in = dr1 (residual). dx_in accumulates
849	        // both the residual AND the attention-input path; stash dx_in into
850	        // fn_xhat (free again). da stays in ctx.
851	        for (int idx = threadIdx.x; idx < dec::kSeq * dec::kD; idx += blockDim.x) {
852	            const int s = idx / dec::kD, j = idx % dec::kD;
853	            sm->fn_xhat[s][j] = sm->ctx[s][j];   // dx_in := dr1 (residual)
854	        }
855	        __syncthreads();
856	        // attn out_proj backward: a = ctx_fwd @ out_w^T + out_b. But ctx_fwd
857	        // (the attention context) was overwritten by the recompute's r1/r2 reuse.
858	        // Recompute ctx_fwd from attn + v (cheap): we still have attn[] and qkv[]
859	        // (v lives in qkv[:,2d:3d]). Rebuild ctx_fwd into x1 scratch (x1 no longer
860	        // needed — ff bwd done).
861	        for (int r = threadIdx.x; r < dec::kSeq * dec::kD; r += blockDim.x) {
862	            const int qi = r / dec::kD, col = r % dec::kD;
863	            const int hh = col / dec::kDhead, t = col % dec::kDhead;
864	            float acc = 0.0f;
865	            #pragma unroll
866	            for (int kj = 0; kj <= qi; ++kj)
867	                acc += sm->attn[hh][qi][kj]
868	                     * sm->qkv[kj][2 * dec::kD + hh * dec::kDhead + t];
869	            sm->x1[qi][col] = acc;   // x1 := ctx_fwd
870	        }
871	        __syncthreads();
872	        // da is in ctx. dW_out += da^T @ ctx_fwd(x1); db_out += sum da;
873	        // dctx = da @ out_w -> store into ff0 scratch (free).
874	        dec_linear_bwd(&sm->ctx[0][0], &sm->x1[0][0], L.out_w, dec::kD, dec::kD,
875	                       G.out_w, G.out_b, &sm->ff0[0][0], /*set_dx=*/true); // dctx->ff0
876	        // ── merge-heads + attention backward (3 synced passes; the forward
877	        //    softmax weights `attn` are read by A and B and NEVER overwritten —
878	        //    dscores go to the dedicated `dsc` buffer). dctx [kSeq,d] is in ff0;
879	        //    v lives in qkv[:,2d:3d], k in qkv[:,d:2d], q in qkv[:,0:d]. dqkv is
880	        //    built into gact[:, :3d]. Transcribed from the oracle's attention bwd:
881	        //      dvh   = attn^T @ dctxh
882	        //      dattn = dctxh @ vh^T ; dscores = softmax_bwd(dattn,attn) * scale
883	        //      dqh   = dscores @ kh ; dkh = dscores^T @ qh                       ─
884	        const float scale = dec::attn_scale();
885	        // A: dv into gact[:, 2d:3d].  dv[kj,qoff+t] = Σ_{qi>=kj} attn[hh][qi][kj]
886	        //    * dctx[qi, qoff+t].  (Owner: thread per (kj, head, t).)
887	        for (int r = threadIdx.x; r < dec::kSeq * dec::kHeads * dec::kDhead;
888	             r += blockDim.x) {
889	            const int kj = r / (dec::kHeads * dec::kDhead);
890	            const int rem = r % (dec::kHeads * dec::kDhead);
891	            const int hh = rem / dec::kDhead, t = rem % dec::kDhead;
892	            const int qoff = hh * dec::kDhead;
893	            float acc = 0.0f;
894	            #pragma unroll
895	            for (int qi = kj; qi < dec::kSeq; ++qi)   // qi>=kj (causal: kj<=qi)
896	                acc += sm->attn[hh][qi][kj] * sm->ff0[qi][qoff + t];
897	            sm->gact[kj][2 * dec::kD + qoff + t] = acc;   // dv block
898	        }
899	        __syncthreads();
900	        // B: dscores into dsc.  datt[hh,qi,kj] = Σ_t dctx[qi,qoff+t]*v[kj,qoff+t];
901	        //    ds = attn*(datt - Σ_k datt*attn)*scale  (masked kj>qi → 0).
902	        for (int r = threadIdx.x; r < dec::kHeads * dec::kSeq; r += blockDim.x) {
903	            const int hh = r / dec::kSeq, qi = r % dec::kSeq;
904	            const int qoff = hh * dec::kDhead;
905	            float datt[dec::kSeq];
906	            #pragma unroll
907	            for (int kj = 0; kj < dec::kSeq; ++kj) {
908	                if (kj > qi) { datt[kj] = 0.0f; continue; }
909	                float acc = 0.0f;
910	                #pragma unroll
911	                for (int t = 0; t < dec::kDhead; ++t)
912	                    acc += sm->ff0[qi][qoff + t]
913	                         * sm->qkv[kj][2 * dec::kD + qoff + t];
914	                datt[kj] = acc;
915	            }
916	            float dot = 0.0f;
917	            #pragma unroll
918	            for (int kj = 0; kj <= qi; ++kj) dot += datt[kj] * sm->attn[hh][qi][kj];
919	            #pragma unroll
920	            for (int kj = 0; kj < dec::kSeq; ++kj) {
921	                float a = sm->attn[hh][qi][kj];
922	                sm->dsc[hh][qi][kj] = (kj <= qi) ? a * (datt[kj] - dot) * scale
923	                                                 : 0.0f;
924	            }
925	        }
926	        __syncthreads();
927	        // C: dq into gact[:,0:d], dk into gact[:,d:2d].
928	        //    dq[qi,qoff+t] = Σ_kj dsc[hh][qi][kj]*k[kj,qoff+t];
929	        //    dk[kj,qoff+t] = Σ_qi dsc[hh][qi][kj]*q[qi,qoff+t].  (Owner: pos,head,t.)
930	        for (int r = threadIdx.x; r < dec::kSeq * dec::kHeads * dec::kDhead;
931	             r += blockDim.x) {
932	            const int pos = r / (dec::kHeads * dec::kDhead);
933	            const int rem = r % (dec::kHeads * dec::kDhead);
934	            const int hh = rem / dec::kDhead, t = rem % dec::kDhead;
935	            const int qoff = hh * dec::kDhead;
936	            float dq = 0.0f, dk = 0.0f;
937	            #pragma unroll
938	            for (int kj = 0; kj < dec::kSeq; ++kj) {
939	                dq += sm->dsc[hh][pos][kj] * sm->qkv[kj][dec::kD + qoff + t];
940	                dk += sm->dsc[hh][kj][pos] * sm->qkv[kj][qoff + t];
941	            }
942	            sm->gact[pos][qoff + t] = dq;            // dq block (gact[:,0:d])
943	            sm->gact[pos][dec::kD + qoff + t] = dk;  // dk block (gact[:,d:2d])
944	        }
945	        __syncthreads();
946	        // in_proj backward: dqkv (gact[:, :3d]) -> dW in, db in, dx_in += dqkv @ in_w.
947	        // x_in = layer_in[li].
948	        dec_linear_bwd(&sm->gact[0][0], &sm->layer_in[li][0][0], L.in_w,
949	                       dec::kD, 3 * dec::kD, G.in_w, G.in_b,
950	                       &sm->fn_xhat[0][0], /*set_dx=*/false);  // dx_in += attn path
951	        // dh for the previous layer = dx_in (in fn_xhat). Move to dh.
952	        for (int idx = threadIdx.x; idx < dec::kSeq * dec::kD; idx += blockDim.x) {
953	            const int s = idx / dec::kD, j = idx % dec::kD;
954	            sm->dh[s][j] = sm->fn_xhat[s][j];
955	        }
956	        __syncthreads();
957	    }
958	
959	    // ── embedding backward: dh = grad wrt h0 [kSeq,d]. tok scatter-add per token
960	    //    id; pos sum over the sample's positions. Owner-thread rule: thread owns
961	    //    column j; loops positions SEQUENTIALLY so colliding token ids accumulate
962	    //    deterministically (mirrors the oracle's index_add_). ──────────────────
963	    for (int j = threadIdx.x; j < dec::kD; j += blockDim.x) {
964	        #pragma unroll
965	        for (int s = 0; s < dec::kSeq; ++s) {
966	            float d = sm->dh[s][j];
967	            g.tok[(int64_t)tokens_s[s] * dec::kD + j] += d;   // single owner: col j
968	            g.pos[(int64_t)s * dec::kD + j] += d;
969	        }
970	    }
971	    __syncthreads();
972	}
